solution.solution.cpp:
#include <algorithm>
#include <vector>

struct Vector2 { float x, y; };
struct Particle { Vector2 pos, vel; float life, maxLife; };

class ParticlePool
{
public:
    explicit ParticlePool(int capacity) : m_items(static_cast<std::size_t>(capacity)) {}

    bool spawn(const Particle& p)
    {
        if (m_count == static_cast<int>(m_items.size())) return false;
        m_items[static_cast<std::size_t>(m_count++)] = p;
        return true;
    }

    void update(float dt, Vector2 gravity)
    {
        int i{ 0 };
        while (i < m_count)
        {
            Particle& p{ m_items[static_cast<std::size_t>(i)] };
            p.vel.x += gravity.x * dt;
            p.vel.y += gravity.y * dt;
            p.pos.x += p.vel.x * dt;
            p.pos.y += p.vel.y * dt;
            p.life -= dt;
            if (p.life <= 0)
            {
                --m_count;
                if (i != m_count)   // the moved particle is updated on the next pass of the loop
                {
                    m_items[static_cast<std::size_t>(i)] = m_items[static_cast<std::size_t>(m_count)];
                }
                continue;
            }
            ++i;
        }
    }

    int count() const { return m_count; }
    const Particle& at(int i) const { return m_items[static_cast<std::size_t>(i)]; }

private:
    std::vector<Particle> m_items;
    int m_count{ 0 };
};

float fadeAlpha(const Particle& p)
{
    const float t{ std::clamp(1.0f - p.life / p.maxLife, 0.0f, 1.0f) };
    return std::clamp(1.0f - t * t, 0.0f, 1.0f);
}

class Emitter
{
public:
    explicit Emitter(float perSecond) : m_rate{ perSecond } {}

    int emit(float dt)
    {
        m_total += m_rate * dt;
        const int whole{ static_cast<int>(m_total) };
        m_total -= static_cast<float>(whole);
        return whole;
    }

private:
    float m_rate;
    float m_total{ 0 };
};

unitTests:
Particle make(float x, float life) { return { { x, 0 }, { 10, 0 }, life, life }; }
TEST("spawning up to capacity") { ParticlePool p{ 2 }; CHECK(p.spawn(make(0, 1))); CHECK(p.spawn(make(0, 1))); CHECK(!p.spawn(make(0, 1))); CHECK_EQ(p.count(), 2); }
TEST("moving with gravity") { ParticlePool p{ 4 }; p.spawn(make(0, 1)); p.update(0.5f, { 0, 100 }); CHECK_NEAR(p.at(0).vel.y, 50.0, 1e-4); CHECK_NEAR(p.at(0).pos.y, 25.0, 1e-4); CHECK_NEAR(p.at(0).pos.x, 5.0, 1e-4); CHECK_NEAR(p.at(0).life, 0.5, 1e-5); }
TEST("dead particles are removed, every one of them") {
    ParticlePool p{ 8 }; p.spawn(make(1, 0.1f)); p.spawn(make(2, 5)); p.spawn(make(3, 0.1f)); p.spawn(make(4, 0.1f)); p.spawn(make(5, 5));
    p.update(0.2f, { 0, 0 });
    CHECK_EQ(p.count(), 2); float xs = p.at(0).pos.x + p.at(1).pos.x; CHECK_NEAR(xs, 2 + 5 + 4.0, 1e-3);
    CHECK_NEAR(p.at(0).life, 4.8, 1e-4); CHECK_NEAR(p.at(1).life, 4.8, 1e-4);
}
TEST("fading") { CHECK_NEAR(fadeAlpha({ {}, {}, 1, 1 }), 1.0, 1e-6); CHECK_NEAR(fadeAlpha({ {}, {}, 0.5f, 1 }), 0.75, 1e-6); CHECK_NEAR(fadeAlpha({ {}, {}, -1, 1 }), 0.0, 1e-6); }
TEST("emitting at a steady rate") {
    Emitter e{ 30 }; int n = 0; for (int i = 0; i < 60; ++i) n += e.emit(1.0f / 60); CHECK_EQ(n, 30);
    Emitter f{ 30 }; CHECK_EQ(f.emit(0.05f), 1); CHECK_EQ(f.emit(0.05f), 2); CHECK_EQ(f.emit(1.0f), 30);
}

